<?php require __DIR__.'/_guard.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){Security::verify();$slug=slugify($_POST['slug']);db()->prepare('INSERT INTO pages(title,slug,body,meta_title,meta_description,status) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE title=VALUES(title),body=VALUES(body),meta_title=VALUES(meta_title),meta_description=VALUES(meta_description),status=VALUES(status)')->execute([$_POST['title'],$slug,$_POST['body'],$_POST['meta_title'],$_POST['meta_description'],$_POST['status']]);$msg='Page saved';}$pages=db()->query('SELECT title,slug,status,updated_at FROM pages ORDER BY title')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/assets/css/admin.css"></head><body><main><a href="/admin/">← Dashboard</a><h1>CMS page manager</h1><p><?=e($msg)?></p><form method="post"><?=Security::field()?><label>Title<input name="title" required></label><label>Slug<input name="slug" required></label><label>Meta title<input name="meta_title"></label><label>Meta description<textarea name="meta_description"></textarea></label><label>Page content<textarea name="body" rows="12"></textarea></label><label>Status<select name="status"><option value="published">Published</option><option value="draft">Draft</option></select></label><button>Save page</button></form><h2>Pages</h2><?php foreach($pages as $p):?><p><?=e($p['title'])?> · /page.php?slug=<?=e($p['slug'])?> · <?=e($p['status'])?></p><?php endforeach;?></main></body></html>